'use client'; // <--- ESTA LINHA CORRIGE O ERRO

import React, { useState } from 'react';
import { Play, FileCode, Database, Zap, CheckCircle, Loader2 } from 'lucide-react';

export default function App() {
  const [loading, setLoading] = useState(false);
  const [response, setResponse] = useState(null);

  // Simulação da chamada ao Backend Python
  const testEndpoint = () => {
    setLoading(true);
    setResponse(null);

    // Num cenário real, aqui você faria: fetch('http://localhost:8000/api/v1/status')
    setTimeout(() => {
      setLoading(false);
      setResponse({
        message: "Bem-vindo à API de mangá Kwordye!",
        timestamp: new Date().toISOString(),
        server: "kwordye-python-backend",
        status: 200
      });
    }, 800);
  };

  // Função para colorir o JSON (Syntax Highlighting simples)
  const renderJson = (json) => {
    if (!json) return null;
    const jsonString = JSON.stringify(json, null, 2);
    return jsonString.split('\n').map((line, i) => {
      const parts = line.split(':');
      if (parts.length > 1) {
        // Tenta colorir chave e valor
        const key = parts[0];
        const val = parts.slice(1).join(':');
        return (
          <div key={i}>
            <span className="text-violet-400">{key}:</span>
            <span className="text-green-400">{val}</span>
          </div>
        );
      }
      return <div key={i} className="text-yellow-300">{line}</div>;
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#0f172a] text-slate-200 font-sans selection:bg-violet-500/30">
      
      {/* Navigation */}
      <nav className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              {/* Using Lucide React Icon instead of FontAwesome for React compatibility */}
              <Database className="text-violet-400 w-6 h-6" />
              <span className="font-bold text-xl tracking-tight text-white">
                Kwordye<span className="text-violet-400">API</span>
              </span>
            </div>
            <div className="hidden md:block">
              <div className="flex items-baseline space-x-8">
                <a href="#" className="text-violet-400 font-medium hover:text-violet-300 transition-colors">Início</a>
                <a href="#docs" className="text-slate-300 hover:text-white transition-colors">Documentação</a>
                <a href="#status" className="text-slate-300 hover:text-white transition-colors">Estado do Sistema</a>
                <a href="#" className="bg-violet-600 hover:bg-violet-700 text-white px-4 py-2 rounded-lg transition-all text-sm font-medium shadow-lg shadow-violet-900/20">
                  Obter Chave API
                </a>
              </div>
            </div>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <main className="flex-grow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
            
            {/* Left Column: Text */}
            <div className="space-y-8 animate-fade-in-up">
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-green-500/10 border border-green-500/20 text-green-400 text-sm font-medium">
                <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
                </span>
                API Online v1.0.0
              </div>
              
              <h1 className="text-5xl md:text-6xl font-bold leading-tight text-white">
                Acesso ilimitado ao mundo do <br />
                <span className="bg-gradient-to-r from-violet-400 to-indigo-400 bg-clip-text text-transparent">
                  Mangá Digital
                </span>
              </h1>
              
              <p className="text-slate-400 text-lg max-w-xl leading-relaxed">
                A API Kwordye fornece dados rápidos e fiáveis sobre milhares de títulos, capítulos e autores. Construída com Python e Google Cloud Platform para máxima performance.
              </p>

              <div className="flex flex-col sm:flex-row gap-4 pt-2">
                <button 
                  onClick={testEndpoint} 
                  className="px-8 py-4 bg-violet-600 hover:bg-violet-700 text-white rounded-xl font-semibold transition-all shadow-lg shadow-violet-600/20 flex items-center justify-center gap-2 active:scale-95 transform duration-200"
                >
                  <Play className="w-5 h-5 fill-current" /> Testar Endpoint
                </button>
                <button className="px-8 py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-semibold transition-all border border-slate-700 flex items-center justify-center gap-2 active:scale-95 transform duration-200">
                  <FileCode className="w-5 h-5" /> Ler Docs
                </button>
              </div>
            </div>

            {/* Right Column: Code Window */}
            <div className="relative group">
              <div className="absolute -inset-1 bg-gradient-to-r from-violet-600 to-indigo-600 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000"></div>
              <div className="relative bg-[#1e293b] rounded-xl overflow-hidden shadow-2xl border border-slate-700">
                <div className="flex items-center justify-between px-4 py-3 border-b border-slate-700 bg-slate-900/80">
                  <div className="flex gap-2">
                    <div className="w-3 h-3 rounded-full bg-red-500"></div>
                    <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
                    <div className="w-3 h-3 rounded-full bg-green-500"></div>
                  </div>
                  <span className="text-xs text-slate-500 font-mono">GET /api/v1/status</span>
                </div>
                
                <div className="p-6 font-mono text-sm overflow-x-auto min-h-[200px] flex flex-col justify-center">
                  {loading ? (
                    <div className="text-slate-400 flex items-center justify-center gap-3">
                      <Loader2 className="animate-spin w-5 h-5 text-violet-400" />
                      A conectar ao Python backend...
                    </div>
                  ) : response ? (
                    <pre className="text-sm">
                      {renderJson(response)}
                    </pre>
                  ) : (
                    <div className="text-slate-500">
                      <span className="text-slate-600">// Clica em "Testar Endpoint" para simular o request</span>
                      <br/>
                      {`{`}
                      <br/>
                      &nbsp;&nbsp;<span className="text-violet-400">"status"</span>: <span className="text-yellow-300">"waiting"</span>,
                      <br/>
                      &nbsp;&nbsp;<span className="text-violet-400">"message"</span>: <span className="text-yellow-300">"À espera de pedido..."</span>
                      <br/>
                      {`}`}
                    </div>
                  )}
                </div>
              </div>
              
              {/* Floating Badge */}
              <div className="absolute -bottom-6 -right-6 bg-slate-800 p-4 rounded-lg border border-slate-700 shadow-xl flex items-center gap-3 animate-bounce" style={{animationDuration: '3s'}}>
                <img src="https://cdn.jsdelivr.net/gh/devicons/devicon/icons/googlecloud/googlecloud-original.svg" className="w-8 h-8" alt="GCP" />
                <div>
                  <p className="text-xs text-slate-400">Powered by</p>
                  <p className="font-bold text-sm text-white">Google Cloud</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Stats Grid */}
        <div id="status" className="bg-slate-900/50 border-y border-slate-800">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {/* Stat Card 1 */}
              <div className="p-6 rounded-2xl bg-slate-800/50 border border-slate-700/50 hover:border-violet-500/50 transition-colors group">
                <div className="w-12 h-12 bg-violet-500/10 rounded-lg flex items-center justify-center mb-4 text-violet-400 group-hover:scale-110 transition-transform">
                  <Database className="w-6 h-6" />
                </div>
                <h3 className="text-xl font-bold mb-2 text-white">Mangás Indexados</h3>
                <p className="text-3xl font-mono font-bold text-white">12,405</p>
                <p className="text-sm text-slate-400 mt-2">+125 adicionados hoje</p>
              </div>
              
              {/* Stat Card 2 */}
              <div className="p-6 rounded-2xl bg-slate-800/50 border border-slate-700/50 hover:border-violet-500/50 transition-colors group">
                <div className="w-12 h-12 bg-blue-500/10 rounded-lg flex items-center justify-center mb-4 text-blue-400 group-hover:scale-110 transition-transform">
                  <Zap className="w-6 h-6" />
                </div>
                <h3 className="text-xl font-bold mb-2 text-white">Latência Média</h3>
                <p className="text-3xl font-mono font-bold text-white">45ms</p>
                <p className="text-sm text-slate-400 mt-2">Otimizado globalmente</p>
              </div>

              {/* Stat Card 3 */}
              <div className="p-6 rounded-2xl bg-slate-800/50 border border-slate-700/50 hover:border-violet-500/50 transition-colors group">
                <div className="w-12 h-12 bg-green-500/10 rounded-lg flex items-center justify-center mb-4 text-green-400 group-hover:scale-110 transition-transform">
                  <CheckCircle className="w-6 h-6" />
                </div>
                <h3 className="text-xl font-bold mb-2 text-white">Uptime</h3>
                <p className="text-3xl font-mono font-bold text-white">99.9%</p>
                <p className="text-sm text-slate-400 mt-2">Últimos 30 dias</p>
              </div>
            </div>
          </div>
        </div>
      </main>

      <footer className="bg-slate-900 border-t border-slate-800 py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center text-slate-500">
          <p>&copy; 2025 Kwordye Manga API. Todos os direitos reservados.</p>
          <p className="text-sm mt-2">Projeto: WhatKindOfReadingDoYouEnjoy</p>
        </div>
      </footer>
    </div>
  );
}